function assertContext(context) {
  if (!context || typeof context !== "object" || Array.isArray(context)) {
    throw new TypeError("buildLumaAuthoringPhases(context) requires an object context.");
  }
  const pageIds = context.pageIds;
  if (!pageIds || typeof pageIds !== "object" || Array.isArray(pageIds)) {
    throw new TypeError("context.pageIds must provide system, screens, and flow page ids.");
  }
  for (const role of Object.keys(PAGE_NAMES)) {
    if (typeof pageIds[role] !== "string" || pageIds[role].trim().length === 0) {
      throw new TypeError(`context.pageIds.${role} must be a non-empty string.`);
    }
  }
  if (new Set(Object.values(pageIds)).size !== 3) {
    throw new TypeError("context.pageIds must resolve three distinct Figma pages.");
  }
}

function serializableCopy(value, fallback) {
  if (value === undefined) return fallback;
  try {
    return JSON.parse(JSON.stringify(value));
  } catch {
    throw new TypeError("context.testLabInput must be JSON-serializable.");
  }
}

