function prototypeCode(config) {
  return nativePrelude(config, "screens") + String.raw`
const page = await figmaPlugin.loadPage(LUMA_CONFIG.pageIds.screens);
const EASE_OUT = { type: "EASE_OUT" }; const EASE_IN_OUT = { type: "EASE_IN_AND_OUT" };
function nav(destinationId, duration) { return { type: "NODE", destinationId, navigation: "NAVIGATE", transition: { type: "SMART_ANIMATE", easing: EASE_IN_OUT, duration: duration || 0.24 }, resetScrollPosition: true }; }
function overlay(destinationId) { return { type: "NODE", destinationId, navigation: "OVERLAY", transition: { type: "MOVE_IN", direction: "BOTTOM", matchLayers: false, easing: EASE_OUT, duration: 0.24 }, resetScrollPosition: true }; }
async function setAction(sourceId, action) { const node = await figmaPlugin.resolveNode(sourceId); figmaPlugin.assert("setReactionsAsync" in node, "Node cannot own reactions: " + sourceId); await node.setReactionsAsync([{ trigger: { type: "ON_CLICK" }, actions: [action] }]); return { sourceId: node.id, sourceName: node.name, destinationId: action.destinationId || null, navigation: action.navigation || action.type }; }
const edges = [];
for (const spec of [["login.submit", nav(registry.screens.home.id)], ["login.face", nav(registry.screens.home.id)], ["state.login-error.submit", nav(registry.screens.home.id)], ["home.transfer", nav(registry.screens.recipient.id, 0.32)], ["home.view-all", nav(registry.screens.history.id)], ["recipient.bank", overlay(registry.overlays.bank.id)], ["recipient.continue", nav(registry.screens.amount.id)], ["amount.review", nav(registry.screens.confirm.id)], ["confirm.submit", nav(registry.screens.success.id, 0.44)], ["confirm.edit", nav(registry.screens.amount.id)], ["success.share", overlay(registry.overlays.share.id)], ["success.transfer-again", nav(registry.screens.recipient.id, 0.32)], ["success.home", nav(registry.screens.home.id)], ["history.detail", overlay(registry.overlays.detail.id)], ["cards.lock", overlay(registry.overlays.lock.id)], ["cards.add-goal", overlay(registry.overlays.goal.id)], ["state.pending.check", nav(registry.screens.history.id)], ["state.failure.retry", nav(registry.screens.amount.id)], ["overlay.lock.confirm", nav(registry.states.lockedCard.id)]]) { const source = registry.actions[spec[0]]; if (source) edges.push(await setAction(source, spec[1])); }
for (const key of Object.keys(registry.overlays)) { const close = registry.actions["overlay." + key + ".close"]; if (close) edges.push(await setAction(close, { type: "CLOSE" })); }
for (const key of ["overlay.bank.select", "overlay.lock.cancel", "overlay.goal.cancel", "overlay.goal.confirm"]) { const source = registry.actions[key]; if (source) edges.push(await setAction(source, { type: "CLOSE" })); }
const backMap = { recipient: registry.screens.home.id, amount: registry.screens.recipient.id, confirm: registry.screens.amount.id };
for (const entry of Object.entries(backMap)) { const screen = await resolve(registry.screens[entry[0]].id, "FRAME"); const back = screen.findOne(function (node) { return controlId(node) === controlId(screen) + "/action/back"; }); if (back) edges.push(await setAction(back.id, nav(entry[1]))); }
const navDestinations = { home: registry.screens.home.id, activity: registry.screens.history.id, cards: registry.screens.cards.id, profile: registry.states.profile.id };
for (const screenKey of ["home", "history", "cards"]) { const screen = await resolve(registry.screens[screenKey].id, "FRAME"); for (const role of Object.keys(navDestinations)) { const actionKey = controlId(screen) + "/nav/" + role; const source = registry.actions[actionKey]; if (source && navDestinations[role] !== screen.id) edges.push(await setAction(source, nav(navDestinations[role]))); } }
page.flowStartingPoints = [{ nodeId: registry.screens.login.id, name: "Flow 01 — Transfer with recovery" }, { nodeId: registry.states.loginError.id, name: "Flow 02 — Login error recovery" }, { nodeId: registry.screens.history.id, name: "Flow 03 — Activity detail" }];
registry.evidence.prototype = { edgeCount: edges.length, startingPoints: page.flowStartingPoints, limitations: ["Single-action reactions only", "Presentation execution remains a separate proof obligation"] }; writeRegistry(registry); const undo = figmaPlugin.commitUndoCheckpoint("Wire Luma prototype graph", registry.evidence.prototype); return { edges, startingPoints: page.flowStartingPoints, limitations: registry.evidence.prototype.limitations, undo };
`;
}

