export function buildLumaAuthoringPhases(context = {}) {
  assertContext(context);
  const config = {
    pageIds: {
      system: context.pageIds.system.trim(),
      screens: context.pageIds.screens.trim(),
      flow: context.pageIds.flow.trim(),
    },
    pageNames: PAGE_NAMES,
    sectionSpecs: SECTION_SPECS,
    registryNamespace: typeof context.registryNamespace === "string" && context.registryNamespace.trim() ? context.registryNamespace.trim() : DEFAULT_REGISTRY_NAMESPACE,
    registryKey: typeof context.registryKey === "string" && context.registryKey.trim() ? context.registryKey.trim() : DEFAULT_REGISTRY_KEY,
    testLabInput: serializableCopy(context.testLabInput, {}),
  };

  const phases = [
    { id: "structure", pageRole: "system", capability: "figma-design-authoring", code: structureCode(config), postconditions: ["Three supplied pages are bound by role without deleting page nodes", "Seven named Sections exist and are persisted in the Luma registry", "Unowned top-level content causes a fail-closed error"] },
    { id: "foundations", pageRole: "system", capability: "figma-tokens", code: foundationsCode(config), postconditions: ["Primitive, semantic, and Motion collections exist without invalid Motion scopes", "Four grid styles and reusable visual styles exist", "Foundations board documents 360/390/430 pressure obligations"] },
    { id: "components", pageRole: "system", capability: "figma-components", code: componentsCode(config), postconditions: ["Seven V2 component sets exist with controlled variant axes", "Editable content is exposed through Text properties", "No legacy component or migration step is created"] },
    { id: "screens", pageRole: "screens", capability: "figma-design-authoring", code: screensCode(config), postconditions: ["Eight 390×844 screens exist directly under the screen Section", "Screens consume V2 component instances and the mobile grid", "Realistic Vietnamese banking content and minimum readable metadata are present"] },
    { id: "states", pageRole: "screens", capability: "figma-design-authoring", code: statesCode(config), postconditions: ["Login error, pending, failure, profile, and locked-card states exist", "Five content-complete overlays exist with explicit close/cancel actions", "All new identities are persisted without historical IDs"] },
    { id: "prototype", pageRole: "screens", capability: "figma-prototype", code: prototypeCode(config), postconditions: ["Primary transfer, navigation, overlay, back, edit, retry, and cancel paths are wired", "Reactions are replaced exactly rather than appended", "Named starting points are persisted with current node IDs"] },
    { id: "motion", pageRole: "flow", capability: "figma-motion", code: motionCode(config), postconditions: ["Success, bottom-sheet, component-state, and reduced-motion specimens exist", "Supported manual keyframes and timeline durations are returned", "Provider-gated Motion failures remain explicit limitations"] },
    { id: "test-lab", pageRole: "flow", capability: "figma-verification", code: testLabCode(config), postconditions: ["Neutral Test Lab shell binds caller-supplied evidence states", "360px and 430px realistic content-pressure specimens exist", "No PASS, bundle revision, or result count is invented by the authoring module"] },
  ];

  for (const phase of phases) {
    if (phase.code.length > MAX_PHASE_CODE_CHARS) {
      throw new Error(`Luma phase ${phase.id} exceeds the ${MAX_PHASE_CODE_CHARS}-character figma_exec budget (${phase.code.length}).`);
    }
  }
  return phases;
}

